def restore(conn,ts):
    tables=['orders','order_lines','events']
    with conn.cursor() as c:
        c.execute('SELECT @@tidb_snapshot');old=c.fetchone()[0]
        try:
            c.execute('SET @@tidb_snapshot=%s',(str(ts),))
            rows=[]
            for t in tables:
                c.execute('SELECT * FROM '+t+' ORDER BY id');rows.append(c.fetchall())
            orders={r[0]:r[1] for r in rows[0]}
            if any(r[1] not in orders for r in rows[1]+rows[2]):raise ValueError('dependency missing')
            if any(sum(r[2] for r in rows[1] if r[1]==i)!=amount for i,amount in orders.items()):raise ValueError('business mismatch')
            c.execute("SET @@tidb_snapshot=''")
            conn.begin()
            current=[]
            for t in tables:
                c.execute('SELECT * FROM recovered_'+t+' ORDER BY id FOR UPDATE');current.append(c.fetchall())
            if current==rows:conn.commit();return tuple(map(len,rows))
            if any(current):raise ValueError('target contains divergent writes')
            for t,data in zip(tables,rows):
                for row in data:c.execute('INSERT INTO recovered_'+t+' VALUES('+','.join(['%s']*len(row))+')',row)
            conn.commit()
            return tuple(map(len,rows))
        except Exception:
            conn.rollback();raise
        finally:c.execute('SET @@tidb_snapshot=%s',(old,))
