def collisions(conn):
    with conn.cursor() as c:
        c.execute('SELECT id,name FROM accounts ORDER BY id')
        rows=c.fetchall()
        groups=[];seen=set()
        for ident,name in rows:
            if ident in seen:continue
            c.execute('SELECT id FROM accounts WHERE name COLLATE utf8mb4_general_ci=%s COLLATE utf8mb4_general_ci ORDER BY id',(name,))
            group=tuple(r[0] for r in c.fetchall());seen.update(group)
            if len(group)>1:groups.append(group)
        return sorted(groups)

