                    conn.commit();return
                c.execute('UPDATE counter SET v=v+%s WHERE id=1',(delta,))
                c.execute('INSERT INTO requests VALUES(%s,%s)',(key,delta))
                c.execute('INSERT INTO outbox VALUES(%s,%s,0)',(key,delta))
                before_commit();conn.commit();return
            except Exception as e:
                conn.rollback()
                if not isinstance(e,pymysql.Error) or not e.args or e.args[0] not in (9007,8028) or attempt+1>=max_attempts:raise
def drain(conn,send):
    with conn.cursor() as c:
